import { test } from 'node:test';
import assert from 'node:assert/strict';
import { frame, createState } from '../game/neon.js';

test('brick collision: ball should bounce', () => {
  const state = createState(1);
  // Position ball so it's about to hit a brick.
  // Brick 0 is at BRICK_TOP (48), width 72, height 20.
  // Ball starting at x=100, y=100, vy=-300.
  // We want it to hit from the bottom.
  state.ball = { x: 100, y: 70, r: 7, vx: 0, vy: -300 }; 
  // Brick at index 0 (if it's there)
  state.bricks[0] = { x: 90, y: 48, w: 72, h: 20, alive: true, points: 50 };

  // Mock ctx
  const ctx = {
    fillStyle: '',
    fillRect: () => {},
    beginPath: () => {},
    arc: () => {},
    fill: () => {},
    fillText: () => {}
  };

  const initialVy = state.ball.vy;
  frame(ctx, state);

  assert.equal(state.bricks[0].alive, false, 'Brick should be dead');
  assert.notEqual(state.ball.vy, initialVy, 'Ball velocity should have changed');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { frame, createState, ballSpeed, BRICK_TOP, BRICK_H, BALL_R } from '../game/neon.js';

const mockCtx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {}
};

function setupState(ball, bricks = []) {
  const state = createState(1);
  state.ball = { ...state.ball, ...ball };
  state.bricks = bricks;
  return state;
}

test('D1: Absence de rebond', () => {
  const state = setupState({ x: 100, y: 70, r: 7, vx: 0, vy: -300 }, [
    { x: 90, y: 48, w: 72, h: 20, alive: true, points: 50 }
  ]);
  const initialVy = state.ball.vy;
  frame(mockCtx, state);
  assert.notEqual(state.ball.vy, initialVy, 'La balle doit rebondir (vy change)');
});

test('D2: Mauvais axe de rebond (impact latéral)', () => {
  const state = setupState({ x: 80, y: 60, r: 7, vx: 300, vy: 0 }, [
    { x: 90, y: 48, w: 72, h: 20, alive: true, points: 50 }
  ]);
  const initialVx = state.ball.vx;
  frame(mockCtx, state);
  assert.ok(state.ball.vx < 0, 'Impact latéral doit inverser vx');
});

test('D3: Collision collante (Sticky)', () => {
  // Position the ball already inside the brick
  const state = setupState({ x: 100, y: 55, r: 7, vx: 0, vy: -300 }, [
    { x: 90, y: 48, w: 72, h: 20, alive: true, points: 50 }
  ]);

  frame(mockCtx, state);

  // The ball should be pushed out of the brick.
  // If it's still inside, it's sticky.
  const ball = state.ball;
  const brick = state.bricks[0];
  const isOverlapping = (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
  assert.equal(isOverlapping, false, 'La balle doit être repositionnée hors de la brique');
});

test('D4: Double inversion (Seam)', () => {
  // Ball hits the corner of two bricks.
  const state = setupState({ x: 95, y: 65, r: 7, vx: 300, vy: -300 }, [
    { x: 90, y: 48, w: 72, h: 20, alive: true, points: 50 },
    { x: 162, y: 48, w: 72, h: 20, alive: true, points: 50 }
  ]);
  // Adjust position to overlap both slightly.
  state.ball.x = 162 - BALL_R / 2; // between the two bricks
  state.ball.y = 48 + BRICK_H / 2; // inside the height

  const initialVx = state.ball.vx;
  const initialVy = state.ball.vy;

  frame(mockCtx, state);

  assert.ok(state.ball.vx !== initialVx, 'vx doit être inversé');
  assert.ok(state.ball.vy !== initialVy, 'vy doit être inversé');
});

test('D5: Traversée (Tunneling) à haut niveau', () => {
  const level = 6;
  const state = createState(level);
  const speed = ballSpeed(level); // 710
  const dt = 0.05;
  const dy = speed * dt; // 35.5

  // Ball is just above the brick, moves fast enough to pass through it.
  // Brick is at 48, height 20.
  // Ball r = 7.
  // Top of ball at t=0 is at y - r.
  // To tunnel: y - r < 48 AND (y - r) + dy > 48 + 20 + 2*r
  // Let's put it at y = 48 + 7 - 1 = 54.
  // At t=0: ball.y = 54, ball.y - r = 47. (Collision not yet)
  // Wait, if I want it to tunnel, it must NOT overlap at t=0, and NOT overlap at t=1.

  state.ball = { x: 100, y: 48 - 10, r: 7, vx: 0, vy: speed }; // Ball at y=38. Bottom at 45.
  // It doesn't overlap.
  // Next frame: y = 38 + 35.5 = 73.5. Bottom at 80.5.
  // Brick is from 48 to 68.
  // At t=0: bottom=45 < brick.y=48. No overlap.
  // At t=1: top=73.5-7=66.5 < 68. overlap!
  // Wait, to tunnel it must be COMPLETELY past.
  // Bottom at t=0: 45.
  // Top at t=1: 73.5 - 7 = 66.5. Still overlaps.

  // Let's try higher speed or larger dt. 
  // Speed at level 10: 260 + 9*90 = 1070. dt=0.05 => 53.5 px.
  // y=38. Bottom=45.
  // Next y = 38 + 53.5 = 91.5. Top = 84.5.
  // Brick bottom = 68.
  // 84.5 > 68. Tunnelling!

  const stateL10 = createState(10);
  stateL10.ball = { x: 100, y: 38, r: 7, vx: 0, vy: ballSpeed(10) };
  stateL10.bricks = [{ x: 90, y: 48, w: 72, h: 20, alive: true, points: 50 }];

  // We need to simulate the game loop call: step(state, dt) then frame(ctx, state)
  // But the bug is that frame() doesn't bounce.
  // If we use a very high speed, the ball can jump over the brick.

  // For the purpose of this test, we just want to see if frame(mockCtx, state) 
  // would have detected the collision if we were at the right spot.
  // But tunneling means it NEVER overlaps.

  // Let's just check if a high-speed ball can pass through without collision.
  // This is a bit different because frame() only checks current overlap.

  // If the ball moves from y=38 to y=91.5, and we only call frame() at those times,
  // it never collides.

  // This is a systemic problem (discrete vs swept).
});

# Playtest: Collision Briques

**Symptôme** : « La balle traverse les briques au lieu de rebondir. »

## D1 — Absence de rebond

- **Famille** : Traversée (Symptôme)
- **Symptôme joueur** : La balle détruit la brique mais continue sa route sans changer de direction.
- **Cause** : `game/neon.js:210` — Le bloc de collision détecte l'impact et marque la brique comme morte, mais n'applique aucune modification à la vitesse de la balle.
- **Invariant violé** : Toute collision avec un obstacle doit entraîner un changement de trajectoire.
- **Déclencheur** : N'importe quelle collision balle/brique.
- **Attendu** : La vitesse de la balle doit être inversée sur l'axe de l'impact.
- **Référence** : [L'algorithme AABB standard](https://noonat.github.io/intersect/) impose un rebond lors d'une intersection.
- **Cas test** :
  ```js
  test('D1: Absence de rebond', () => {
    const state = setupState({ x: 100, y: 70, r: 7, vx: 0, vy: -300 }, [
      { x: 90, y: 48, w: 72, h: 20, alive: true, points: 50 }
    ]);
    const initialVy = state.ball.vy;
    frame(mockCtx, state);
    assert.notEqual(state.ball.vy, initialVy, 'La balle doit rebondir');
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: La balle doit rebondir (vy change)`
- **Discrimine** : Une implémentation qui oublierait d'appeler la logique de rebond.
- **Vert quand** : `state.ball.vy` (ou `vx`) change après `frame()`.
- **Révélé par** : -

## D2 — Mauvais axe de rebond

- **Famille** : Face vs Coin
- **Symptôme joueur** : La balle rebondit verticalement même quand elle frappe le côté d'une brique.
- **Cause** : `game/neon.js:210` — L'absence de détection de la face touchée conduit souvent à une correction naïve `vy = -vy` systématique.
- **Invariant violé** : Le rebond doit être perpendiculaire à la face touchée.
- **Déclencheur** : Impact latéral (`|vx| > 0` et collision sur les bords gauche/droit de la brique).
- **Attendu** : `vx` est inversé lors d'un impact latéral.
- **Référence** : [AABB Corner Resolution](https://learnopengl.com/In-Practice/2D-Collision-resolution) : l'axe de rebond est celui de la plus petite pénétration.
- **Cas test** :
  ```js
  test('D2: Mauvais axe de rebond (impact latéral)', () => {
    const state = setupState({ x: 80, y: 60, r: 7, vx: 300, vy: 0 }, [
      { x: 90, y: 48, w: 72, h: 20, alive: true, points: 50 }
    ]);
    const initialVx = state.ball.vx;
    frame(mockCtx, state);
    assert.ok(state.ball.vx < 0, 'Impact latéral doit inverser vx');
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Impact latéral doit inverser vx`
- **Discrimine** : La correction naïve `ball.vy *= -1` qui ignore l'axe X.
- **Vert quand** : `vx` est inversé lors d'un impact latéral.
- **Révélé par** : D1.

## D3 — Collision collante (Sticky)

- **Famille** : Collant
- **Symptôme joueur** : La balle semble "vibrer" ou rester collée à la brique avant de s'en extraire.
- **Cause** : `game/neon.js:210` — Inversion de la vitesse sans repositionnement de la balle hors de l'obstacle.
- **Invariant violé** : Après résolution, la balle doit être strictement hors du rectangle de l'obstacle.
- **Déclencheur** : Pénétration profonde ou `dt` élevé.
- **Attendu** : La balle est repositionnée sur le bord de la brique après le rebond.
- **Référence** : [Sweets AABB/Collision Response](https://gamedev.net/community/forums/game-physics-forums/swept-aabb-collision-detection-and-response) : repositionner l'objet pour éviter le re-trigger immédiat.
- **Cas test** :
  ```js
